import at.pinzker.taskloop.*;
public class AlarmRulesTests {
 static int n;static void check(boolean value,String label){n++;if(!value)throw new AssertionError(label);}static void near(float a,float b,String label){check(Math.abs(a-b)<0.00001f,label);}
 public static void main(String[] args){String[] commands={"Alarm","lauter Alarm","nur Benachrichtigung","alarm","loud alarm","notification only"};int[] mode={0,1,2,0,1,2};for(int i=0;i<commands.length;i++){AlarmRules.Command c=AlarmRules.command("Rechnung prüfen, "+commands[i]+".");check(c.mode==mode[i],commands[i]);check(c.text.equals("Rechnung prüfen"),"remove command "+i);}check(AlarmRules.command("Lauter Alarm im Haus prüfen").mode==-1,"not in middle");check(AlarmRules.command("Alarmanlage prüfen").mode==-1,"not partial word");check(AlarmRules.command("Lautsprecher einstellen").mode==-1,"not loud synonym");check(AlarmRules.command("LAUTER ALARM").mode==1,"case insensitive");check(AlarmRules.command("nur Benachrichtigung").text.isEmpty(),"command only");check(AlarmRules.command("Aufgabe erledigen").mode==-1,"no command retains selection");near(AlarmRules.volume(0,30000,1,100,true),0.01f,"initial");near(AlarmRules.volume(15000,30000,1,100,true),0.505f,"half");near(AlarmRules.volume(30000,30000,1,100,true),1f,"target");near(AlarmRules.volume(60000,30000,1,100,true),1f,"clamped end");near(AlarmRules.volume(-100,30000,1,100,true),0.01f,"clamped start");near(AlarmRules.volume(0,30000,1,75,false),0.75f,"loud immediate");near(AlarmRules.volume(0,0,1,50,true),0.50f,"zero duration");near(AlarmRules.volume(0,30000,90,40,true),0.40f,"start capped to target");near(AlarmRules.volume(0,30000,0,200,false),1f,"target clamp");System.out.println("PASS: "+n+" alarm commands and volume checks");}
}
